"""Generate Ghostty's Midnight MacBook theme from the local Zed theme."""
from pathlib import Path
import sys
import tempfile

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from theme_utils import color as theme_color, CONFIG_ROOT, load_style

config = CONFIG_ROOT
target = config / "ghostty/themes/Midnight MacBook"
style = load_style()


def color(key):
    return theme_color(style, key)[:7]


lines = [
    "# Generated by theme-sync. Edit the Zed theme instead.",
    f"background = {color('background')}",
    f"foreground = {color('terminal.foreground')}",
    f"cursor-color = {color('text.accent')}",
    f"selection-background = {color('element.selected')}",
    f"selection-foreground = {color('terminal.foreground')}",
]
background = theme_color(style, "background")
if len(background) == 9:
    lines.append(f"background-opacity = {int(background[7:9], 16) / 255:.2f}")
names = ["black", "red", "green", "yellow", "blue", "magenta", "cyan", "white"]
for index, name in enumerate(names + ["bright_" + name for name in names]):
    lines.append(f"palette = {index}={color('terminal.ansi.' + name)}")
content = "\n".join(lines) + "\n"
target.parent.mkdir(parents=True, exist_ok=True)
if not target.exists() or target.read_text() != content:
    with tempfile.NamedTemporaryFile(mode="w", dir=target.parent, prefix=".theme-", delete=False) as file:
        temporary = Path(file.name)
        file.write(content)
    try:
        temporary.replace(target)
    finally:
        temporary.unlink(missing_ok=True)
print("Synced Midnight MacBook: Zed → Ghostty. Reload Ghostty with ⌘⇧,.")
